// Extract first image URL from a Markdown image tag in the assistant message
function extractFirstImageUrl(content: string): string | null {
  if (!content) return null;
  const m = content.match(/!\[[^\]]*\]\((https?:\/\/[^\s)]+|data:image\/[^)]+)\)/);
  return m ? m[1] : null;
}

// Extract first video URL from <video src="..."> or markdown ![..](...)
function extractFirstVideoUrl(content: string): string | null {
  if (!content) return null;
  const v = content.match(/<video\s+[^>]*src=['"]([^'"]+)['"]/i);
  if (v) return v[1];
  const m = content.match(/!\[[^\]]*\]\((https?:\/\/[^\s)]+)\)/);
  return m ? m[1] : null;
}

// Build a hint string the LLM/upstream can pick up describing the user's
// requested duration/aspect/audio. flow2api currently embeds the spec into
// the model id itself (veo_X_Y_aspect_resolution), so this is just metadata
// for logging + future expansion.
function describeVideoConfig(config: VideoConfig, model: VideoModel): string {
  const parts = [
    `aspect=${config.aspectRatio}`,
    `duration=${config.duration}s`,
    `resolution=${config.resolution}`,
    `audio=${config.audio === false ? "off" : config.audio === true ? "on" : "default"}`,
    `refs=${(config.imageBase64 || []).length}`,
    `mode=${Array.isArray(config.mode) ? config.mode.join(",") : config.mode}`,
  ];
  return parts.join(" ");
}

const textRequest = (model: TextModel, _think: boolean, _tl: 0 | 1 | 2 | 3) => {
  if (!vendor.inputValues.apiKey) throw new Error("Missing API Key");
  const apiKey = vendor.inputValues.apiKey.replace(/^Bearer\s+/i, "");
  return createOpenAICompatible({ name: "bridge", baseURL: vendor.inputValues.baseUrl, apiKey }).chatModel(model.modelName);
};

const imageRequest = async (config: ImageConfig, model: ImageModel): Promise<string> => {
  if (!vendor.inputValues.apiKey) throw new Error("Missing API Key");
  const apiKey = vendor.inputValues.apiKey.replace(/^Bearer\s+/i, "");
  const baseUrl = vendor.inputValues.baseUrl;
  const refs = config.imageBase64 || [];
  const messages: any[] = [];
  if (refs.length) {
    messages.push({ role: "user", content: refs.map((b) => ({ type: "image_url", image_url: { url: b } })) });
  }
  messages.push({ role: "user", content: config.prompt });

  const body: any = { model: model.modelName, messages };
  // bridge sidecar: tag this generation under a project so /v1/files can list it
  body.project_name = `toonflow-${model.modelName}`;

  logger(`[imageRequest] ${model.modelName} aspect=${config.aspectRatio} size=${config.size} refs=${refs.length}`);
  const r = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`flow2api-bridge HTTP ${r.status}: ${await r.text()}`);
  const data = await r.json();
  const content = data?.choices?.[0]?.message?.content || "";
  const ga = data?.generated_assets || {};
  const url = ga.final_image_url || ga.origin_image_url || extractFirstImageUrl(content);
  if (!url) throw new Error("No image URL in response: " + content.slice(0, 200));
  if (url.startsWith("data:image")) return url;
  const b64 = await urlToBase64(url);
  return b64.startsWith("data:") ? b64 : `data:image/png;base64,${b64}`;
};

const videoRequest = async (config: VideoConfig, model: VideoModel): Promise<string> => {
  if (!vendor.inputValues.apiKey) throw new Error("Missing API Key");
  const apiKey = vendor.inputValues.apiKey.replace(/^Bearer\s+/i, "");
  const baseUrl = vendor.inputValues.baseUrl;

  // Reference images (i2v / r2v): same OpenAI multi-modal shape as imageRequest.
  const refs = config.imageBase64 || [];
  const messages: any[] = [];
  if (refs.length) {
    messages.push({
      role: "user",
      content: refs.map((b) => ({ type: "image_url", image_url: { url: b } })),
    });
  }

  // Append a one-line config hint to the prompt. Veo encodes most of the
  // dial-tone (aspect, resolution) into model id, but the LLM may use the
  // duration/audio hint to shape its output. Harmless if upstream ignores.
  const promptWithHints = `${config.prompt}\n\n[generation hints: ${describeVideoConfig(config, model)}]`;
  messages.push({ role: "user", content: promptWithHints });

  const body: any = { model: model.modelName, messages };
  // Bridge sidecar tags this generation under a project so /v1/files lists it.
  body.project_name = `toonflow-${model.modelName}`;

  logger(`[videoRequest] ${model.modelName} ${describeVideoConfig(config, model)}`);
  const r = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  if (!r.ok) throw new Error(`flow2api-bridge HTTP ${r.status}: ${await r.text()}`);
  const data = await r.json();
  const content = data?.choices?.[0]?.message?.content || "";
  const ga = data?.generated_assets || {};
  const url = ga.final_video_url || ga.origin_video_url || extractFirstVideoUrl(content);
  if (!url) throw new Error("No video URL in response: " + content.slice(0, 300));
  if (url.startsWith("data:")) return url;
  const b64 = await urlToBase64(url);
  return b64.startsWith("data:") ? b64 : `data:video/mp4;base64,${b64}`;
};

